function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // child
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 25);
  ctx.lineTo(W/2 - 70, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 25);
  ctx.lineTo(W/2 - 30, H/2 + 40);
  ctx.stroke();

  // dog
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20 * Math.sin(t), H/2 + 20, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 40);
  ctx.lineTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 45);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 45);
  ctx.lineTo(W/2 + 70 + 20 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  // growing up
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Age: ' + Math.floor(5 + 5 * Math.sin(t)), 10, 10);

  ctx.restore();
}
